package main

import "fmt"

type TrieNode struct {
	children [26]*TrieNode // one slot per letter, nil when no word continues that way
	isWord   bool          // a word ends here
}

func (t *TrieNode) Insert(word string) {
	node := t
	for i := 0; i < len(word); i++ {
		c := word[i] - 'a' // 'a' is 0, 'z' is 25
		if node.children[c] == nil {
			node.children[c] = &TrieNode{}
		}
		node = node.children[c]
	}
	node.isWord = true
}

func (t *TrieNode) Search(word string) bool {
	node := t
	for i := 0; i < len(word); i++ {
		node = node.children[word[i]-'a']
		if node == nil {
			return false // the path breaks off
		}
	}
	return node.isWord
}

func main() {
	var n int
	fmt.Scan(&n)
	trie := &TrieNode{}
	for i := 0; i < n; i++ {
		var w string
		fmt.Scan(&w)
		trie.Insert(w)
	}
	var q int
	fmt.Scan(&q)
	for ; q > 0; q-- {
		var w string
		fmt.Scan(&w)
		if trie.Search(w) {
			fmt.Println(w, "yes")
		} else {
			fmt.Println(w, "no")
		}
	}
}

