package main

import "fmt"

type TrieNode struct {
	children [26]*TrieNode // one slot per letter, nil when no word continues that way
	isWord   bool          // a word ends here
}

func (t *TrieNode) Insert(word string) {
	node := t
	for i := 0; i < len(word); i++ {
		c := word[i] - 'a' // 'a' is 0, 'z' is 25
		if node.children[c] == nil {
			node.children[c] = &TrieNode{}
		}
		node = node.children[c]
	}
	node.isWord = true
}

// count returns how many words below node match pattern from index i on.
func count(node *TrieNode, pattern string, i int) int {
	if node == nil {
		return 0
	}
	if i == len(pattern) {
		if node.isWord {
			return 1
		}
		return 0
	}
	if pattern[i] == '.' {
		total := 0
		for _, child := range node.children {
			total += count(child, pattern, i+1)
		}
		return total
	}
	return count(node.children[pattern[i]-'a'], pattern, i+1)
}

func main() {
